25	/**
26	 * Builds an owner's {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>}: the region code,
27	 * the two-digit fiscal year of the registration date, {@code HASH8} (the first eight upper-case
28	 * hexadecimal characters of the SHA-256 digest over the owner's normalized telephone followed by
29	 * their last name), and a single Luhn check digit computed over the digits of the
30	 * {@code <REGION><FY><HASH8>} prefix (e.g. {@code NSW261A2B3C4D7}).
31	 */
32	@Component
33	public class MemberIdGenerator {
34	
35	    private static final int HASH_LENGTH = 8;
36	
37	    /**
38	     * Build the member id for an owner.
39	     *
40	     * @param region           the owner's region code, forming the leading segment
41	     * @param telephone        the owner's normalized telephone; hashed together with the last name
42	     * @param lastName         the owner's last name; hashed together with the telephone
43	     * @param registrationDate the owner's registration date; its fiscal year supplies the two-digit FY segment
44	     * @return the formatted member id, e.g. {@code NSW261A2B3C4D7}
45	     */
46	    public String generate(String region, String telephone, String lastName, LocalDate registrationDate) {
47	        String hash8 = Sha256Hex.upperHexPrefix(telephone + lastName, HASH_LENGTH);
48	        String base = String.format("%s%02d%s", region, FiscalYear.of(registrationDate).getShortYear(), hash8);
49	        return base + LuhnCheckDigit.of(base);
50	    }
51	}
