29	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
30	import org.springframework.samples.petclinic.rest.controller.BusinessDayResolver;
31	import org.springframework.samples.petclinic.rest.controller.DuplicateOwnerIdentityException;
32	import org.springframework.samples.petclinic.rest.controller.EmailNormalizer;
33	import org.springframework.samples.petclinic.rest.controller.FutureRegistrationDateException;
34	import org.springframework.samples.petclinic.rest.controller.IdempotencyKeyRegistry;
35	import org.springframework.samples.petclinic.rest.controller.OwnerAuditLogger;
36	import org.springframework.samples.petclinic.rest.controller.OwnerCityCapacityExceededException;
37	import org.springframework.samples.petclinic.rest.controller.OwnerDailyRegistrationLimitExceededException;
38	import org.springframework.samples.petclinic.rest.controller.OwnerFieldsValidator;
39	import org.springframework.samples.petclinic.rest.controller.PostcodeValidator;
40	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
41	import org.springframework.samples.petclinic.model.Owner;
42	import org.springframework.samples.petclinic.model.Pet;
43	import org.springframework.samples.petclinic.model.Visit;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.PetDto;
48	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.samples.petclinic.service.HouseholdIdGenerator;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final OwnerFieldsValidator ownerFieldsValidator;
79	
80	    private final PostcodeValidator postcodeValidator;
81	
82	    private final TelephoneNormalizer telephoneNormalizer;
83	
84	    private final EmailNormalizer emailNormalizer;
85	
86	    private final AddressNormalizer addressNormalizer;
87	
88	    private final BusinessDayResolver businessDayResolver;
89	
90	    private final OwnerAuditLogger ownerAuditLogger;
91	
92	    private final HouseholdIdGenerator householdIdGenerator;
93	
94	    private final IdempotencyKeyRegistry idempotencyKeyRegistry;
95	
96	    /** Maximum number of owners a single city may hold before further creations are rejected. */
97	    static final long MAX_OWNERS_PER_CITY = 50;
98	
99	    /** Number of owners already in a city at or above which a new owner is flagged as approaching the per-city capacity limit. */
100	    static final long CAPACITY_WARNING_THRESHOLD = 40;
101	
102	    /** Maximum number of owners that may be registered on a single day before further creations are rejected. */
103	    static final long MAX_OWNERS_PER_DAY = 100;
104	
105	    /** Number of owners already registered on a day above which a new owner is flagged with a bulk-signup warning. */
106	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
107	
108	    public OwnerRestControllerV1(ClinicService clinicService,
109	                                 OwnerMapper ownerMapper,
110	                                 PetMapper petMapper,
111	                                 VisitMapper visitMapper,
112	                                 OwnerFieldsValidator ownerFieldsValidator,
113	                                 PostcodeValidator postcodeValidator,
114	                                 TelephoneNormalizer telephoneNormalizer,
115	                                 EmailNormalizer emailNormalizer,
116	                                 AddressNormalizer addressNormalizer,
117	                                 BusinessDayResolver businessDayResolver,
118	                                 OwnerAuditLogger ownerAuditLogger,
119	                                 HouseholdIdGenerator householdIdGenerator,
120	                                 IdempotencyKeyRegistry idempotencyKeyRegistry) {
121	        this.clinicService = clinicService;
122	        this.ownerMapper = ownerMapper;
123	        this.petMapper = petMapper;
124	        this.visitMapper = visitMapper;
125	        this.ownerFieldsValidator = ownerFieldsValidator;
126	        this.postcodeValidator = postcodeValidator;
127	        this.telephoneNormalizer = telephoneNormalizer;
128	        this.emailNormalizer = emailNormalizer;
129	        this.addressNormalizer = addressNormalizer;
130	        this.businessDayResolver = businessDayResolver;
131	        this.ownerAuditLogger = ownerAuditLogger;
132	        this.householdIdGenerator = householdIdGenerator;
133	        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
139	        Collection<Owner> owners;
140	        if (lastName != null) {
141	            owners = this.clinicService.findOwnerByLastName(lastName);
142	        } else {
143	            owners = this.clinicService.findAllOwners();
144	        }
145	        if (owners.isEmpty()) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
164	        Integer existingOwnerId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
165	        if (existingOwnerId != null) {
166	            Owner existingOwner = this.clinicService.findOwnerById(existingOwnerId);
167	            if (existingOwner != null) {
168	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
169	            }
170	        }
171	        this.normalizeAddress(ownerFieldsDto);
172	        this.ownerFieldsValidator.validate(ownerFieldsDto);
173	        this.postcodeValidator.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
174	        HttpHeaders headers = new HttpHeaders();
175	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
176	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
177	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
178	        LocalDate serverDate = LocalDate.now();
179	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
180	            throw new FutureRegistrationDateException(owner.getRegistrationDate(), serverDate);
181	        }
182	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : serverDate;
183	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
184	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
185	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
186	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
187	        }
188	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
189	        long ownersInCity = this.clinicService.countOwnersInCity(owner.getCity());
190	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
191	            throw new OwnerCityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
192	        }
193	        owner.setCapacityWarning(ownersInCity >= CAPACITY_WARNING_THRESHOLD);
194	        if (owner.getPostcode() != null) {
195	            owner.setHouseholdId(this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
196	        }
197	        if (!this.clinicService.findOwnersByIdentityKey(owner.getIdentityKey()).isEmpty()) {
198	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
199	        }
200	        Owner softMatch = this.clinicService.findSoftMatchOf(owner);
201	        if (softMatch != null) {
202	            owner.setPossibleDuplicateOf(softMatch.getId());
203	        }
204	        this.clinicService.saveOwner(owner);
205	        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
206	        this.ownerAuditLogger.logCreated(owner);
207	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
208	        headers.setLocation(UriComponentsBuilder.newInstance()
209	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
210	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
211	    }
212	
213	    /**
214	     * Canonicalize the request's address fields in place, preferring the structured form. When a
215	     * non-blank {@code addressLine1} is supplied it and the optional {@code addressLine2} are
216	     * normalized and the composed value stored on {@code address}; otherwise only the flat
217	     * {@code address} is normalized. This keeps the stored {@code address} the single canonical
218	     * value everything downstream reads.
219	     */
220	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
221	        if (ownerFieldsDto.getAddressLine1() != null && !ownerFieldsDto.getAddressLine1().isBlank()) {
222	            ownerFieldsDto.setAddressLine1(this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine1()));
223	            String line2 = this.addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
224	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
225	            ownerFieldsDto.setAddress(
226	                this.addressNormalizer.compose(ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2()));
227	        }
